CALLOUTS = ['7 дней бесплатно', 'Без банковской карты', 'Без автосписаний', 'Разговор в Telegram']
def qlinks(e):
    S = SITE[e]; u = S['url']
    QD = dict(sofia='Разобраться с деньгами и увереннее строить планы', alisa='Нравиться, знакомиться и получать больше взаимности')  # benefit > 60
    return [(S['cta'], QD.get(e, S['benefit']), u),
            ('Как начать', 'Откройте Telegram, нажмите «Начать» и расскажите о себе', u + '#how'),
            ('Пример разговора', 'Посмотрите, как проходит личный разговор в Telegram', u + '#chat'),
            ('Все ИИ-эксперты EYRA', 'Десять личных ИИ-экспертов в Telegram на выбор', 'https://eyra.ink/#experts')]
NARROW = set('.,!:;"\'')
def dlen(t): return len([c for c in t if c not in NARROW]), sum(c in NARROW for c in t)
def ok(t, lim, narrow=True):
    L, n = dlen(t); longw = max(len(w) for w in re.split(r'[\s—]+', t) if w)
    good = (L <= lim and n <= 15) if narrow else len(t) <= lim
    return good and longw <= 22, (L if narrow else len(t)), len(t)
