    g, L, T = ok(PATH[e], 20, False); bad += not g; rows.append([e, '', '', 'отображаемая ссылка', PATH[e], u, 20, L, T, 'OK' if g else 'FAIL'])
    for n, (t1, t2, tx) in enumerate(ADS[e], 1):
        slug = B[e][n-1][0]; files = f'creatives/{e}/{n}-{slug}-{{4x3,1x1,16x9,3x4}}.jpg'
        for fld, t, lim in (('заголовок', t1, 56), ('доп. заголовок', t2, 30), ('текст', tx, 81)):
            g, L, T = ok(t, lim); bad += not g; rows.append([e, n, files, fld, t, u, lim, L, T, 'OK' if g else 'FAIL'])
        md.append(f'| {n} | `{n}-{slug}` «{B[e][n-1][1].replace("|", " ")}» | {t1} | {t2} | {tx} |')
    md += ['', 'Быстрые ссылки:', '']
    for t, dsc, lu in qlinks(e):
        for fld, x, lim in (('быстрая ссылка', t, 30), ('описание б/с', dsc, 60)):
            g, L, T = ok(x, lim, False); bad += not g; rows.append([e, '', '', fld, x, lu, lim, L, T, 'OK' if g else 'FAIL'])
        md.append(f'- **{t}** — {dsc} → {lu}')
    md.append('')
